/* Path: static/style.css */
/* Purpose: Stylesheet for ACM Problem-Solving Platform */

/* General Reset */
body, h1, h2, h3, p, ul, ol, li, a, button {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

/* Body Styling */
body {
    font-family: Arial, sans-serif;
    line-height: 1.6;
    background-color: #f4f4f9;
    color: #333;
}

/* Header */
header {
    background: #007bff;
    color: #fff;
    padding: 10px 20px;
    text-align: center;
    font-size: 1.5em;
}

/* Navigation Bar */
.navbar {
    display: flex;
    justify-content: space-between;
    background: #0056b3;
    padding: 10px 20px;
}

.navbar a {
    color: #fff;
    text-decoration: none;
    margin: 0 10px;
    font-weight: bold;
}

.navbar a:hover {
    text-decoration: underline;
}

/* Main Content */
main {
    padding: 20px;
    background: #fff;
    margin: 20px auto;
    max-width: 1200px;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
    border-radius: 5px;
}

/* Problem Cards */
.problem-card {
    border: 1px solid #ddd;
    margin: 10px 0;
    padding: 15px;
    border-radius: 5px;
    background: #f9f9f9;
    transition: 0.3s ease;
}

.problem-card:hover {
    background: #eef;
    transform: translateY(-2px);
}

.problem-card h2 {
    color: #007bff;
    font-size: 1.2em;
    margin-bottom: 10px;
}

.problem-card p {
    font-size: 0.9em;
    color: #555;
}

/* Buttons */
.button {
    display: inline-block;
    padding: 10px 15px;
    color: #fff;
    background: #007bff;
    border: none;
    border-radius: 5px;
    text-decoration: none;
    font-size: 0.9em;
    transition: 0.3s ease;
    cursor: pointer;
}

.button:hover {
    background: #0056b3;
}

/* Forms */
form {
    margin: 20px 0;
    display: flex;
    flex-direction: column;
}

form label {
    font-size: 0.9em;
    margin-bottom: 5px;
    color: #333;
}

form input, form textarea, form select {
    padding: 10px;
    margin-bottom: 15px;
    border: 1px solid #ddd;
    border-radius: 5px;
    font-size: 0.9em;
}

form input:focus, form textarea:focus, form select:focus {
    border-color: #007bff;
    outline: none;
}

/* Footer */
footer {
    background: #0056b3;
    color: #fff;
    text-align: center;
    padding: 10px 20px;
    margin-top: 20px;
    font-size: 0.8em;
}

/* Leaderboard */
.leaderboard {
    margin: 20px 0;
    border-collapse: collapse;
    width: 100%;
}

.leaderboard th, .leaderboard td {
    border: 1px solid #ddd;
    padding: 10px;
    text-align: left;
}

.leaderboard th {
    background: #007bff;
    color: #fff;
}

.leaderboard tr:nth-child(even) {
    background: #f4f4f9;
}

.leaderboard tr:hover {
    background: #eef;
}

